import sys, random, itertools, inspect, warnings
warnings.simplefilter('ignore')
sys.path.insert(0, sys.argv[1]); sys.path.insert(0, sys.argv[2])
import more_itertools as new, mi_ref as old
def run(f, *a):
    try:
        r = f(*a)
        if hasattr(r,'__iter__') and not isinstance(r,(str,bytes,list,tuple,dict,set)):
            r = list(itertools.islice(r, 200))
            r = [list(x) if hasattr(x,'__next__') or type(x).__name__ in('_islice','islice','map','filter','generator') else x for x in r]
        return ('ok', repr(r))
    except Exception as e:
        return ('err', type(e).__name__)
names = sorted(set(old.__all__) & set(new.__all__))
argsets = lambda: [
 (list(range(random.randint(0,8))),),
 ([random.randint(0,5) for _ in range(random.randint(0,9))],),
 ([random.randint(0,5) for _ in range(random.randint(0,9))], random.randint(1,4)),
 ([random.randint(0,5) for _ in range(random.randint(0,9))], random.randint(0,4)),
 (random.randint(1,4),[random.randint(0,5) for _ in range(random.randint(0,9))]),
 ([random.randint(0,5) for _ in range(random.randint(0,9))],[random.randint(0,5) for _ in range(random.randint(0,9))]),
 ((lambda x: x%2==0), [random.randint(0,9) for _ in range(random.randint(0,9))]),
 ([random.randint(0,9) for _ in range(random.randint(0,9))], (lambda x: x%2==0)),
]
skip={'random_product','random_permutation','random_combination','random_combination_with_replacement','sample','random_derangement','consume','nth_combination_with_replacement'}
bad={}
for n in names:
    if n in skip: continue
    for t in range(300):
        random.seed(t)
        for a in argsets():
            random.seed(hash(repr(a)))
            o = run(getattr(old,n), *a); random.seed(hash(repr(a)))
            w = run(getattr(new,n), *a)
            if o!=w and not (o[0]=='err' and w[0]=='err'):
                bad.setdefault(n,(a,o,w))
for n,v in bad.items(): print(n, v)
